-- ============================================================================
-- Online technical MCQ bank («آزمون تستی») — seed for comp_mcq_questions (schema.sql Section 56).
-- Written for the 12 job roles that have in-person technical bank questions; seeded APPROVED and
-- active. Each row: [category, topic, difficulty 1-3, stem, [4 options], correct option index 0-3,
-- explanation, standard reference]. The options are rotated on insert so the correct answers spread
-- evenly over the four positions (the candidate additionally sees a per-test random order). Categories follow the in-person bank's keys so results feed the
-- same competencies (TECHNICAL_MCQ evidence). Idempotent: on conflict (job_role, md5(stem)) do
-- nothing — re-running never overwrites an edited question. The other job roles in
-- comp_job_role_config can be added later with the same statement shape.
-- ============================================================================

-- welding_inspector: 48 questions
insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'welding_inspector', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
